{"expression": "var tooltip: String = "Meteorfall\nAt the start of your next turn this tile takes %d damage%s.%s" % [
			damage,
			" and becomes %s" % surface.capitalize() if not surface.is_empty() else "",
			"\nYou are standing on it." if tile == player_tile else ""
		]", "kind": "code", "line": 6843, "literal": ""Meteorfall\nAt the start of your next turn this tile takes %d damage%s.%s"", "location": "scripts/combat_board_view.gd:6843", "path": "scripts/combat_board_view.gd", "scope": "_draw_meteor_mark_badges", "span": [341128, 341203]}

{"expression": "_log(next_state, "%s breaks through terrain for %d." % [
		str(GameData.enemy_def(str(enemy.get("type", ""))).get("name", "Enemy")),
		damage
	])", "kind": "code", "line": 6346, "literal": ""%s breaks through terrain for %d."", "location": "scripts/combat_engine.gd:6346", "path": "scripts/combat_engine.gd", "scope": "_enemy_attack_blocking_terrain", "span": [334988, 335023]}

{"expression": "_log(next_state, "%s hardens for %d stoneskin." % [
				str(GameData.enemy_def(str(enemy.get("type", ""))).get("name", "Enemy")),
				int(action.get("amount", 0))
			])", "kind": "code", "line": 4450, "literal": ""%s hardens for %d stoneskin."", "location": "scripts/combat_engine.gd:4450", "path": "scripts/combat_engine.gd", "scope": "_resolve_enemy_action", "span": [237569, 237599]}

{"expression": "_log(next_state, "%s guards all other enemies for %d block." % [
					_enemy_display_name(enemy),
					int(action.get("amount", 0))
				])", "kind": "code", "line": 4490, "literal": ""%s guards all other enemies for %d block."", "location": "scripts/combat_engine.gd:4490", "path": "scripts/combat_engine.gd", "scope": "_resolve_enemy_action", "span": [239430, 239473]}

{"expression": "_log(next_state, "%s guards %s for %d block." % [
					_enemy_display_name(enemy),
					"itself" if guard_target_index == enemy_index else _enemy_display_name(guard_target),
					int(action.get("amount", 0))
				])", "kind": "code", "line": 4504, "literal": ""%s guards %s for %d block."", "location": "scripts/combat_engine.gd:4504", "path": "scripts/combat_engine.gd", "scope": "_resolve_enemy_action", "span": [240167, 240195]}

{"expression": "_log(next_state, "%s stitches %s for %d health." % [
					_enemy_display_name(enemy),
					"itself" if heal_target_index == enemy_index else _enemy_display_name(heal_target),
					healed_amount
				])", "kind": "code", "line": 4471, "literal": ""%s stitches %s for %d health."", "location": "scripts/combat_engine.gd:4471", "path": "scripts/combat_engine.gd", "scope": "_resolve_enemy_action", "span": [238618, 238649]}

{"expression": "_log(next_state, "%s braces for %d block." % [
				str(GameData.enemy_def(str(enemy.get("type", ""))).get("name", "Enemy")),
				int(action.get("amount", 0))
			])", "kind": "code", "line": 4443, "literal": ""%s braces for %d block."", "location": "scripts/combat_engine.gd:4443", "path": "scripts/combat_engine.gd", "scope": "_resolve_enemy_action", "span": [237269, 237294]}

{"expression": ""DEFIANCE restores %d health. %d remaining." % [
			int(player.get("hp", restored_hp)),
			remaining_before - 1
		]", "kind": "code", "line": 10965, "literal": ""DEFIANCE restores %d health. %d remaining."", "location": "scripts/combat_engine.gd:10965", "path": "scripts/combat_engine.gd", "scope": "_trigger_defiance", "span": [567112, 567156]}

{"expression": "return {"id":"emaciated_services", "npc_id":"emaciated_man", "speaker":"Emaciated Man", "accent":"#b8aa90", "lines":[{
		"speaker":"Emaciated Man", "service":true, "text":"%s\n%s" % [speech, summary],
		"options":[
			{"label":"Trade 1 Shard → %d Embers" % ProgressionStore.MOLT_EXCHANGE_EMBERS, "action":"exchange_moltshard", "disabled":shards < 1, "tooltip":"Exchange one Moltshard for %d Embers." % ProgressionStore.MOLT_EXCHANGE_EMBERS if shards > 0 else "You need 1 Moltshard. The first dragon defeated each run grants one."},
			{"label":"Maximum Level" if maximum else "Level Up · %d Embers" % cost, "action":"emaciated_level_up", "disabled":not ProgressionStore.can_level_up(progression), "tooltip":"Maximum level reached." if maximum else "Spend %d Embers to gain a level and a skill point." % cost},
			{"label":"Leave", "action":"close"}
		]
	}]}", "kind": "code", "line": 125, "literal": ""Emaciated Man"", "location": "scripts/dialogue_engine.gd:125", "path": "scripts/dialogue_engine.gd", "scope": "emaciated_service_dialogue", "span": [5267, 5282]}

{"expression": "body.append("%s %s equipment. Adds %d card%s to the deck while equipped." % [
		rarity,
		slot_label,
		card_count,
		"" if card_count == 1 else "s"
	])", "kind": "code", "line": 955, "literal": ""%s %s equipment. Adds %d card%s to the deck while equipped."", "location": "scripts/grimoire_library.gd:955", "path": "scripts/grimoire_library.gd", "scope": "_equipment_entry_body", "span": [39351, 39412]}

{"expression": "umbra_subtitle.tooltip_text = "%s Umbra\nPersonal vision: %s.\nTiles outside your vision or a light source are obscured. Hidden enemies cannot be targeted and conceal their intents.\nRadiance can reveal them or drive the Umbra back." % [
		stage_name,
		radius_text
	]", "kind": "code", "line": 14574, "literal": ""%s Umbra\nPersonal vision: %s.\nTiles outside your vision or a light source are obscured. Hidden enemies cannot be targeted and conceal their intents.\nRadiance can reveal them or drive the Umbra back."", "location": "scripts/run_scene.gd:14574", "path": "scripts/run_scene.gd", "scope": "_refresh_umbra_subtitle", "span": [685487, 685690]}
